import open from 'open';
import chalk from 'chalk';
import readline from 'readline';
import fs from 'fs';
import path from 'path';
import { Command } from 'commander';

const program = new Command();

program.command('start')
.option('--fixed', 'open fixed editor')
.option('--viewer', 'open viewer')
.option('--latest', 'open latest editor')
.action((opt, options) => {
  if (opt.fixed) {
    open('https://lh4.googleusercontent.com/V9-lste4omDVt7XWkMnSv2iRmHuLvQFxY0c4nJPh9Flhxl4mMnUqTepVbTAgZUamkA589Y37Idn3UdZBoxbql1dPOT_BQo0G9cwkJR4Yd9vOCdLPPIFh0nhANyTFANV0wvxGRWTynUv2');
    return;
  } else if (opt.viewer) {
    open('https://artemy1.wixsite.com/my-site-46');
    return;
  }
  const editor = "https://editor.wix.com/html/editor/web/renderer/edit/aa56e917-9da3-41f2-bdda-c1ea0d476f0a?_gl=1*15ico5i*_ga*MTI4NzgzMDgyMC4xNjM4OTUyMDIw*_ga_H314XQHSPY*MTY0NDM1MjgzNy4xLjEuMTY0NDM1Mjg1MS40Ng..&editorSessionId=1609f36f-a509-47eb-8552-95fd6ead7715&metaSiteId=df53d8b9-3f00-4b5c-a194-c7f869a07fc3";
  const viewer = 'https://artemy1.wixsite.com/my-site-46';

  const CTRL_C = '\u0003';

  console.log(
    chalk.greenBright.bold(`\nPress key to open a URL with overrides:`),
  );
  console.log(chalk.greenBright.italic(`Press with a SHIFT to copy the URL`));
  console.log(`   > ${chalk.bold(1)}: Editor`);
  console.log(`   > ${chalk.bold(2)}: Viewer`);

  const rl = readline.createInterface(process.stdin);
  readline.emitKeypressEvents(process.stdin, rl);
  process.stdin.setRawMode(true);
  process.stdin.setEncoding('utf8');

  process.stdin.on('keypress', (str) => {
    if (str === CTRL_C) {
      process.stdin.setRawMode(false);
      process.exit(0);
      return;
    }
    console.clear();
    if (str == 1) {
      console.log(
        chalk.greenBright.bold(`\nPress key to open a URL with overrides:`),
      );
      console.log(chalk.greenBright.italic(`Press with a SHIFT to copy the URL`));
      console.log(`   > ${chalk.bold(1)}: Editor ${chalk.green('- Opened ✔')}`);
      console.log(`   > ${chalk.bold(2)}: Viewer`);
      open(editor);
      return;
    } else if (str == 2) {
      console.log(
        chalk.greenBright.bold(`\nPress key to open a URL with overrides:`),
      );
      console.log(chalk.greenBright.italic(`Press with a SHIFT to copy the URL`));
      console.log(`   > ${chalk.bold(1)}: Editor`);
      console.log(`   > ${chalk.bold(2)}: Viewer ${chalk.green('- Opened ✔')}`);
      open(viewer);
      return;
    } else if (str == 3) {
      console.log(
        chalk.greenBright.bold(`\nPress key to open a URL with overrides:`),
      );
      console.log(chalk.greenBright.italic(`Press with a SHIFT to copy the URL`));
      console.log(`   > ${chalk.bold(1)}: Editor`);
      console.log(`   > ${chalk.bold(2)}: Viewer`);
      console.log(``);
      console.log(chalk.bold.greenBright(`   ⚠️ The local code is out of sync. Please press 1 to open the Editor.`));
      return;
    }
    return;
  });

  return;
});

program.command('deploy')
.option('--production', 'deploy to production')
.action((opt, options) => {
  console.log(`${chalk.gray('Uploading...')}

${chalk.bold(`Revision ${chalk.bold.greenBright(123)} was deployed.`)}

${chalk.blue('Deploy preview URL:')} ${chalk.blue.underline('http://wix.to/XYvTmg4')}
`);
});

program.command('install')
.argument('<dependency>', 'dependency name')
.action((dependency) => {
  console.log(`  ${chalk.gray(`Installing ${dependency} dependency...`)}

  ${chalk.greenBright(`✔️ ${chalk.bold(dependency)} installed`)}
`);
  const config = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'site.config.json'), 'utf-8'));
  config.dependencies[dependency] = '4.5.0';
  fs.writeFileSync(path.join(process.cwd(), 'site.config.json'), JSON.stringify(config, null, 2));

});

program.command('login')
.action((dependency) => {
  console.log(`  ${chalk.gray(`Signing in...`)}`);
  open('https://users.wix.com/signin');
  console.log();
  console.log(`  ${chalk.greenBright(`You have been successfully authenticated with ${chalk.bold('artemy@wix.com')}.`)}`);
});

program.command('whoami')
.action((dependency) => {
  console.log(`  ${chalk.greenBright(`${chalk.bold('artemy@wix.com')}.`)}`);
});

program.command('logout')
.action((dependency) => {
  console.log(`  ${chalk.gray(`Logging out...`)}`);
  console.log(`  ${chalk.greenBright(`You have been successfully loged out`)}`);
});

program.parse()
console.log('Started');